import re

with open('registry.yaml', 'r') as f:
    lines = f.readlines()

# Index
exp_lines = {}
for i, line in enumerate(lines):
    if line.startswith('  ') and ':' in line and not line.startswith('    '):
        exp_name = line.strip().rstrip(':')
        exp_lines[exp_name] = i

# Additional targets not yet confirmed
additional = [
    'qwen15b_vota_seed456',
    'qwen15b_ae_only_seed456',
    'codellama13b_vota_seed456',
    'codellama13b_no_trace_seed123',
    'codellama13b_no_trace_seed456',
    'deepseek_ae_only_seed456',
]

for target in additional:
    if target in exp_lines:
        start_line = exp_lines[target]
        # Look for accuracy in next 150 lines
        accuracy = None
        notes = None
        for i in range(start_line, min(start_line + 150, len(lines))):
            if 'accuracy:' in lines[i] and accuracy is None:
                match = re.search(r'accuracy:\s+([\d.]+)', lines[i])
                if match:
                    accuracy = match.group(1)
            if 'notes:' in lines[i] and notes is None:
                notes = lines[i].split('notes:', 1)[1].strip()
        print(f"{target}: accuracy={accuracy}, exists=True")
    else:
        print(f"{target}: DOES NOT EXIST")

